    super(ctx, env);
    ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS hits (at INTEGER NOT NULL)');
  }

  async onStart() {
    // Cron schedules are idempotent, so this doesn't add a row on every restart.
    await this.scheduler.set(DAILY_COMPACT_CRON, 'compact');
  }

  async hit() {
    // Native RPC bypasses automatic startup; start it so the daily schedule gets registered.
    await this.lifecycle.start();
